"""Build supabase/seed.sql from data/clean CSVs (pure SQL; run with psql or the Supabase SQL editor)."""
import pandas as pd
from pathlib import Path
R = Path(__file__).resolve().parent.parent; C = R/'data/clean'
q = lambda v: 'NULL' if pd.isna(v) else "'" + str(v).replace("'", "''") + "'"
rd = lambda n: pd.read_csv(C/f'{n}.csv', dtype=str)
zones, sheds, mf, cl, lo, iss = (rd(n) for n in ['zones','sheds','manufacturers','loco_classes','locomotives','import_issues'])
o = ['-- GENERATED by scripts/make_seed.py. Source: Loco_Data_Base.xlsx (user-provided). Re-run to regenerate.','begin;']
o.append(f"insert into import_batches (source_file, source_label, rows_read, rows_loaded, rows_flagged, notes) values ('Loco_Data_Base.xlsx','User-provided shed allocation sheet',16179,{len(lo)},{len(iss)},'Initial load; verification=source_listed');")
o.append('insert into zones (code,name) values ' + ','.join(f'({q(a)},{q(b)})' for a,b in zones[['code','name']].values) + ';')
o.append('insert into manufacturers (code,slug) values ' + ','.join(f'({q(a)},{q(b)})' for a,b in mf[['code','slug']].values) + ';')
o.append('insert into loco_classes (code,slug) values ' + ','.join(f'({q(a)},{q(b)})' for a,b in cl[['code','slug']].values) + ';')
o.append('insert into sheds (code,name,location,maps_query,zone_id,slug) select v.c,v.n,v.l,v.m,z.id,v.s from (values ' +
  ','.join(f'({q(r.code)},{q(r["name"])},{q(r.location)},{q(r.maps_query)},{q(r.zone_code)},{q(r.slug)})' for _,r in sheds.iterrows()) +
  ') v(c,n,l,m,z,s) left join zones z on z.code=v.z;')
rows = [f'({r.number},{q(r.class_code)},{q(r.shed_code)},{q(r.zone_code)},{q(r.manufacturer_code)},{q(r.kavach_make)})' for r in lo.itertuples()]
for i in range(0, len(rows), 2000):
    o.append('insert into locomotives (number,class_id,shed_id,zone_id,manufacturer_id,kavach_make,source_batch_id) select v.n,c.id,s.id,z.id,m.id,v.k,(select max(id) from import_batches) from (values ' + ','.join(rows[i:i+2000]) +
      ') v(n,c,s,z,m,k) join loco_classes c on c.code=v.c join sheds s on s.code=v.s join zones z on z.code=v.z left join manufacturers m on m.code=v.m;')
o.append('insert into import_issues (batch_id,source_row,issue_type,detail) values ' + ','.join(f'((select max(id) from import_batches),{int(r.source_row)},{q(r.issue_type)},{q(r.detail)})' for r in iss.itertuples()) + ';')
o.append("do $$ begin if (select count(*) from locomotives) <> %d then raise exception 'locomotive count mismatch'; end if; end $$;" % len(lo))
o.append('commit;')
(R/'supabase/seed.sql').write_text('\n'.join(o)); print(len(o), 'statements;', (R/'supabase/seed.sql').stat().st_size//1024, 'KB')
